 function startNewCompetency(){setActiveDraftId(`draft-${Date.now()}`);setDraftLoaded(true);setSelectedPublication(null);setTitle("");setDescription("");setSelectedColor(palette[0]);setSequenceName("Séquence 1");setSequenceColor(palette[0]);setActivityName("");setSequences([]);setCourseLayout("hero");setCompetence("");setObjective("");setContentText("");setContentFiles([]);setPendingFiles([]);setStep(1);const owner=demoMode?`demo:${demoName}`:`account:${authEmail||"user"}`;localStorage.removeItem(`trainer-draft:${owner}`);setView("create")}
